use std::collections::HashSet;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Role {
    Knight,
    Knave,
    Spy,
}

fn statement_truth(speaker: Role, claim: bool) -> bool {
    // Returns true if the speaker is allowed to make a statement with this truth value.
    match speaker {
        Role::Knight => claim,        // must be true
        Role::Knave => !claim,        // must be false
        Role::Spy => true,            // either is fine
    }
}

fn main() {
    let roles = [Role::Knight, Role::Knave, Role::Spy];
    let mut solutions = Vec::new();

    for &alice in &roles {
        for &bob in &roles {
            for &charlie in &roles {
                // Each role assigned exactly once
                let set: HashSet<_> = [alice, bob, charlie].into_iter().collect();
                if set.len() != 3 {
                    continue;
                }

                // Alice: "Charlie is a knave."
                let alice_claim = charlie == Role::Knave;
                // Bob: "Alice is a knight."
                let bob_claim = alice == Role::Knight;
                // Charlie: "I am the spy."
                let charlie_claim = charlie == Role::Spy;

                if statement_truth(alice, alice_claim)
                    && statement_truth(bob, bob_claim)
                    && statement_truth(charlie, charlie_claim)
                {
                    solutions.push((alice, bob, charlie));
                }
            }
        }
    }

    println!("Found {} valid assignment(s):", solutions.len());
    for (a, b, c) in &solutions {
        println!("  Alice = {:?}, Bob = {:?}, Charlie = {:?}", a, b, c);
    }
}
